from twisted.internet import reactor

class SIPClient:
    def __init__(self, username, password, domain):
        self.agent = Agent(username, password, domain)

    def start(self):
        self.agent.register().addCallback(self.on_registered).addErrback(self.on_failure)
        reactor.run()

    def on_registered(self, session):
        print("Registered with SIP server")
        self.session = session

    def on_failure(self, failure):
        print(f"Registration failed: {failure}")

    def call(self, to):
        self.session.call(to).addCallback(self.on_call).addErrback(self.on_failure)

    def on_call(self, call):
        print(f"Called {call.peer}")
        call.hangup()

    def send_message(self, to, message):
        self.session.message(to, message).addCallback(self.on_message).addErrback(self.on_failure)

    def on_message(self, message):
        print(f"Message sent to {message.to}: {message.body}")

    def join_conference(self, conference):
        self.session.conference(conference).addCallback(self.on_conference).addErrback(self.on_failure)

    def on_conference(self, conference):
        print(f"Joined conference {conference.name}")
        conference.leave()

    def on_failure(self, failure):
        print(f"Failed: {failure}")

if __name__ == "__main__":
