        if isinstance(msg, Image):
            return self.parse_image(msg)
        elif isinstance(msg, PointCloud2):
            return self.parse_pointcloud2(msg)
        elif isinstance(msg, LaserScan):
            return self.parse_laserscan(msg)
        elif isinstance(msg, CameraInfo):
            return self.parse_camera_info(msg)
        else:
            return None

    def get_data(self, bag, topics):
        data = {}
        for topic in topics:
            data[topic] = []

        for topic, msg, t in bag.read_messages(topics=topics):
            parsed_data = self.parse_msg(msg)
            if parsed_data is not None:
                data[topic].append((msg.header.stamp.to_sec(), parsed_data))

        for topic in topics:
            data[topic] = sorted(data[topic], key=lambda x: x[0])

