        image_data = self.read_image()
        if new_format == 'jpeg':
            self.write_image(image_data, 'jpeg')
        elif new_format == 'png':
            self.write_image(image_data, 'png')
        else:
            raise ValueError("Unsupported format. Only 'jpeg' and 'png' are supported.")

