class OpenJPEG:
    def __init__(self, filename):
        self.filename = filename
        self.image = openjpeg.openjpeg_read(filename)
        self.metadata = {}

    def read_image(self):
        # Convert openjpeg image to numpy array
        return np.array(self.image)

    def write_image(self, filename):
        # Convert numpy array back to openjpeg image
        image = openjpeg.openjpeg_write(np.array(self.image), filename)
        self.image = image

    def get_metadata(self):
        # Retrieve metadata from openjpeg image
        self.metadata = openjpeg.openjpeg_get_metadata(self.image)
        return self.metadata

    def convert_format(self, format):
        # Convert openjpeg image to a different format
        if format == 'jpg':
            image = Image.fromarray(np.array(self.image)).convert('RGB')
            image.save(self.filename, 'JPEG')
        elif format == 'png':
            image = Image.fromarray(np.array(self.image)).convert('RGBA')
            image.save(self.filename, 'PNG')
        else:
            raise ValueError('Unsupported format. Only jpg and png are supported.')

