from google.appengine.ext import ndb

class User(ndb.Model):
    _user = ndb.UserProperty()
    email = ndb.StringProperty()

class MainHandler(webapp2.RequestHandler):
    def get(self):
        user = users.get_current_user()

        if user:
            logout_url = users.create_logout_url('/')
            greeting = 'Welcome, {}'.format(user.nickname())

            user_record = User.query().filter(User._user == user).get()

            if not user_record:
                user_record = User(
                    _user=user,
                    email=user.email()
                )
                user_record.put()

        else:
            login_url = users.create_login_url('/')
            greeting = 'Hello, guest'

        self.response.write('<html><body>')
        self.response.write('<h1>{}</h1>'.format(greeting))

        if user:
            self.response.write('<a href="{}">sign out</a>'.format(logout_url))
        else:
            self.response.write('<a href="{}">sign in</a>'.format(login_url))

        self.response.write('</body></html>')

app = webapp2.WSGIApplication([
    ('/', MainHandler)
], debug=True)

