from google.cloud import storage
from google.cloud import appengine

class DeployApp:
    def __init__(self, project_id, bucket_name, app_dir, app_name):
        self.project_id = project_id
        self.bucket_name = bucket_name
        self.app_dir = app_dir
        self.app_name = app_name
        self.client = storage.Client(project=project_id)
        self.bucket = self.client.get_bucket(bucket_name)
        self.appengine_client = appengine.ApplicationsClient()

    def upload_to_bucket(self):
        blob = self.bucket.blob(self.app_name)
        blob.upload_from_filename(self.app_dir)

    def deploy_to_app_engine(self):
        parent = self.appengine_client.project_path(self.project_id)
        version = self.appengine_client.create_version(
            parent,
            {
                "runtime": "python39",
                "entrypoint": {
                    "shell": "python3 main.py"
                },
                "env_variables": {
                    "BUCKET_NAME": self.bucket_name
                }
            },
            version_id="v1"
        )
        print("Deployed version {}".format(version.name))

if __name__ == "__main__":
    deploy_app = DeployApp("YourProjectID", "YourBucketName", "YourAppDirectory", "YourAppName")
    deploy_app.upload_to_bucket()
    deploy_app.deploy_to_app_engine()

