import boto3
from dateutil import parser

def parse_cron_expressions(log_events):
    cron_expressions = {}

    for event in log_events:
        message = event.get('message', '')
        timestamp = parser.parse(event['timestamp'])

        if 'cron(' in message:
            # Extract the cron expression
            cron_expr = message.split('cron(')[1].split(')')[0]
            cron_expressions[cron_expr] = timestamp

    return cron_expressions

def format_cron_expressions(cron_expressions):
    for cron_expr, timestamp in cron_expressions.items():
        print(f"Cron Expression: {cron_expr}\nLast Executed: {timestamp}\n")

def main():
    client = boto3.client('logs')

    response = client.filter_log_events(
        logGroupName='/aws/lambda/your_lambda_function',
        filterPattern='cron('
    )

    cron_expressions = parse_cron_expressions(response['events'])
    format_cron_expressions(cron_expressions)

if __name__ == "__main__":
    main()
